#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *g[] = {"+-+-+", "| | |", "+-+-+"};
    assert(count_rectangles(g, 3) == 3);
    const char *b[] = {"+--+", "|  |", "+ -+"};
    assert(count_rectangles(b, 3) == 0);
    assert(count_rectangles(NULL, 0) == 0);
    {
        const char *values[] = {NULL};
        assert(count_rectangles(values, 0) == 0);
    }
    {
        const char *values[] = {""};
        assert(count_rectangles(values, 1) == 0);
    }
    {
        const char *values[] = {" "};
        assert(count_rectangles(values, 1) == 0);
    }
    {
        const char *values[] = {"+-+", "| |", "+-+"};
        assert(count_rectangles(values, 3) == 1);
    }
    {
        const char *values[] = {"  +-+", "  | |", "+-+-+", "| |  ", "+-+  "};
        assert(count_rectangles(values, 5) == 2);
    }
    {
        const char *values[] = {"  +-+", "  | |", "+-+-+", "| | |", "+-+-+"};
        assert(count_rectangles(values, 5) == 5);
    }
    {
        const char *values[] = {"+--+", "+--+"};
        assert(count_rectangles(values, 2) == 1);
    }
    {
        const char *values[] = {"++", "||", "++"};
        assert(count_rectangles(values, 3) == 1);
    }
    {
        const char *values[] = {"++", "++"};
        assert(count_rectangles(values, 2) == 1);
    }
    {
        const char *values[] = {"  +-+", "    |", "+-+-+", "| | -", "+-+-+"};
        assert(count_rectangles(values, 5) == 1);
    }
    {
        const char *values[] = {"+------+----+", "|      |    |", "+---+--+    |",
                                "|   |       |", "+---+-------+"};
        assert(count_rectangles(values, 5) == 3);
    }
    {
        const char *values[] = {"+------+----+", "|      |    |", "+------+    |",
                                "|   |       |", "+---+-------+"};
        assert(count_rectangles(values, 5) == 2);
    }
    {
        const char *values[] = {"+---+--+----+", "|   +--+----+", "+---+--+    |",
                                "|   +--+----+", "+---+--+--+-+", "+---+--+--+-+",
                                "+------+  | |", "          +-+"};
        assert(count_rectangles(values, 8) == 60);
    }
    {
        const char *values[] = {"+-+ +-+", "| | | |", "+-+-+-+", "  | |  ",
                                "+-+-+-+", "| | | |", "+-+ +-+"};
        assert(count_rectangles(values, 7) == 5);
    }
    return 0;
}
